            /// <summary>{{ p.property_name }} の確定値が変更される直前に呼ばれる（新値のみ。partial 実装で処理を追加）</summary>
            partial void On{{ p.property_name }}Changing({{ p.type_name }} value);

            /// <summary>{{ p.property_name }} の確定値が変更される直前に呼ばれる（旧値・新値。partial 実装で処理を追加）</summary>
            partial void On{{ p.property_name }}Changing({{ p.type_name }} oldValue, {{ p.type_name }} newValue);

            /// <summary>{{ p.property_name }} の確定値が変更された直後に呼ばれる（新値のみ。partial 実装で処理を追加）</summary>
            partial void On{{ p.property_name }}Changed({{ p.type_name }} value);

            /// <summary>{{ p.property_name }} の確定値が変更された直後に呼ばれる（旧値・新値。partial 実装で処理を追加）</summary>
            partial void On{{ p.property_name }}Changed({{ p.type_name }} oldValue, {{ p.type_name }} newValue);

            /// <summary>{{ p.property_name }} の画面入力用バインディング文字列（設定時に確定値へ変換）</summary>
            public string {{ p.binding_property_name }}
            {
                get => {{ p.binding_field_name }};
                set
                {
                    if (!SetProperty(ref {{ p.binding_field_name }}, value, nameof({{ p.binding_property_name }})))
                    {
                        return;
                    }

                    if (!IsReverting)
                    {
        {{ if p.needs_parse }}                if ({{ p.parse_type_name }}.TryParse(value, out var parsed))
                        {
                            {{ p.property_name }} = parsed;
                            {{ p.error_field_name }} = null;
                            SetError(nameof({{ p.binding_property_name }}), null);
                        }
                        else
                        {
                            {{ p.error_field_name }} = ResolveParseErrorMessage(nameof({{ p.binding_property_name }}), value, "{{ p.parse_type_name }}");
                            SetError(nameof({{ p.binding_property_name }}), {{ p.error_field_name }});
                        }
        {{ else if p.is_binary }}                if (string.IsNullOrEmpty(value))
                        {
                            {{ p.property_name }} = Array.Empty<byte>();
                            SetError(nameof({{ p.binding_property_name }}), null);
                        }
                        else
                        {
                            try
                            {
                                {{ p.property_name }} = Convert.FromBase64String(value);
                                SetError(nameof({{ p.binding_property_name }}), null);
                            }
                            catch (FormatException)
                            {
                                SetError(nameof({{ p.binding_property_name }}), ResolveParseErrorMessage(nameof({{ p.binding_property_name }}), value, "byte[]"));
                            }
                        }
        {{ else if p.is_nullable }}                if (string.IsNullOrEmpty(value))
                        {
                            {{ p.property_name }} = null;
                            SetError(nameof({{ p.binding_property_name }}), null);
                        }
                        else
                        {
                            {{ p.property_name }} = value;
                            SetError(nameof({{ p.binding_property_name }}), null);
                        }
        {{ else }}                {{ p.property_name }} = value;
                        SetError(nameof({{ p.binding_property_name }}), null);
        {{ end }}            }
                }
            }

        {{ end }}    // ---- navigation ----
        {{ for navigation in item.navigations }}    /// <summary>{{ navigation.property_name }} ナビゲーションプロパティ</summary>
            public {{ navigation.display_type_name }} {{ navigation.property_name }} { get; set; }{{ navigation.initializer }}

        {{ end }}    /// <summary>確定値をバインディング用プロパティへ書き戻しエラーをクリアする</summary>
